def main():
    p = "/root/.openclaw/workspace/index.html"
    s = io.open(p, encoding="utf-8").read()
    tag0 = '\n "potongan": {'
    if tag0 in s and ENDTAG in s:
        a = s.index(tag0); b = s.index(ENDTAG) + len(ENDTAG)
        s = s[:a] + s[b:]
        io.open(p, "w", encoding="utf-8").write(s)
        print("previous B reverted")
    marker = "const bitVocabDB = {"
    i = s.index(marker); j = s.index("{", i)
    depth = 0; in_str = False; esc = False; q = ""
    end = -1
    for k in range(j, len(s)):
        ch = s[k]
        if in_str:
            if esc: esc = False; continue
            if ch == "\\": esc = True; continue
            if ch == q: in_str = False
            continue
        if ch in ('"', "'", "`"): in_str = True; q = ch; continue
        if ch == "{": depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0: end = k; break
    block = s[j:end+1]
    for e in ENTRIES:
        key = e["word"].lower()
        if re.search(r'(?m)^\s*"%s":' % re.escape(key), block):
            raise SystemExit("collision: " + key)
    lines = "".join('\n "%s": %s,' % (e["word"].lower(), json.dumps(e, ensure_ascii=False)) for e in ENTRIES)
    new = s[:end] + lines + "\n " + ENDTAG + s[end:]
    io.open(p, "w", encoding="utf-8").write(new)
    print("B inserted", len(ENTRIES))

main()
